const prSW = {}
const baseUrl = 'https://pub-4211d6b528d54ed69e8ec217f023723e.r2.dev/'

onmessage = ev => {
	const data = ev.data
	if ('sw' in data && ('cache' in data.sw || 'cached' in data.sw)) {
		if (data.sw?.set && data.sw?.lang) {
			const name = `${data.sw?.set}-${data.sw?.lang}`
			prSW[name]?.resolve(data.sw)
		}
	}
}
(async () => {
	const exts = await fetch('db/img-exts.json').then(res => res.json())
	for (const ext of exts) {
		let _resolve
		const name = `${ext.name}-${ext.lang}`
		const download = prSW[name] = new Promise(resolve => {
			_resolve = async o => {
				if (o.cache) {
					const remaining = ext.total - Object.keys(o.cache).length
					if (!remaining) return resolve('skipped')

					const files = await fetch(ext.path.replace(/^\//, '')).then(res => res.json()).then(files => files.map(f => encodeURIComponent(f)))
					const toDownload = files.filter(f => !o.cache['/' + f])
					if (!toDownload.length) return resolve('skipped')

					postMessage({ sw: { cache: { set: ext.name, lang: ext.lang, urls: toDownload.map(filename => `${baseUrl}${filename}`) } } })
				} else if ('cached' in o) {
					if (o.error) console.error(o.error)
					postMessage({ progress: { nbFiles: o.total, downloaded: o.cached } })
					resolve()
				}
			}
		})
		prSW[name].resolve = _resolve
		postMessage({ sw: { getCache: { set: ext.name, lang: ext.lang } } })
		const status = await download
		if (status !== 'skipped') await new Promise(resolve => setTimeout(resolve, 250))
	}
})()